import torch
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void avg_pool_1d_kernel(
    const half* input,
    half* output,
    int batch_size,
    int in_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * in_channels * output_length;

    if (idx >= total_elements) return;

    int batch_idx = idx / (in_channels * output_length);
    int channel_idx = (idx % (in_channels * output_length)) / output_length;
    int out_pos = idx % output_length;

    int start_input = out_pos * stride - padding;
    int actual_start = max(0, start_input);
    int actual_end = min(input_length, start_input + kernel_size);
    int valid_count = actual_end - actual_start;

    if (valid_count <= 0) {
        output[idx] = __float2half(0.0f);
        return;
    }

    float sum = 0.0f;
    for (int i = actual_start; i < actual_end; ++i) {
        int input_idx = batch_idx * (in_channels * input_length) + 
                       channel_idx * input_length + 
                       i;
        sum += __half2float(input[input_idx]);
    }

    float avg = sum / valid_count;
    output[idx] = __float2half(avg);
}

void launch_avg_pool_1d(
    const half* input,
    half* output,
    int batch_size,
    int in_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding
) {
    int total_elements = batch_size * in_channels * output_length;
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    avg_pool_1d_kernel<<<grid_size, block_size>>>(
        input, output, batch_size, in_channels, input_length,
        output_length, kernel_size, stride, padding
    );
}
"""

model_new = load_inline(
    name="avg_pool_1d",
    cuda_sources=[cuda_source],
    functions=["launch_avg_pool_1d"],
    verbose=True
)

class ModelNew(torch.nn.Module):
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, in_channels, input_length = x.shape
        output_length = (input_length + 2 * self.padding - self.kernel_size) // self.stride + 1

        # Ensure input is on GPU and in fp16
        if x.device.type != 'cuda':
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.to(torch.float16)

        # Allocate output tensor
        output = torch.empty(batch_size, in_channels, output_length, dtype=torch.float16, device=x.device)

        # Launch kernel
        model_new.launch_avg_pool_1d(
            x.data_ptr(),
            output.data_ptr(),
            batch_size,
            in_channels,
            input_length,
            output_length,
            self.kernel_size,
            self.stride,
            self.padding
        )

        return output

